SELECT
  DATE_FORMAT(p.income_Date, '%Y-%m') AS expenseMonth,
  COALESCE(SUM(p.total_Price), 0) AS totalExpense
FROM purchase p
WHERE p.b_Id = #{bId}
  AND p.income_Date >= #{startDate}
  AND p.income_Date < #{endDate}
GROUP BY DATE_FORMAT(p.income_Date, '%Y-%m')
ORDER BY expenseMonth

SELECT
COALESCE(SUM(p.total_Price), 0)
FROM purchase p
WHERE p.b_Id = #{bId}
AND p.income_Date >= #{startDate}
AND p.income_Date < #{endDate}

SELECT
  COALESCE(
    ROUND(
      SUM(d.disposalCountAll) * 100 / NULLIF(SUM(f.foodMaterialCountAll), 0),
      2
    ),
    0
  ) AS disposalRate
FROM DISPOSALS d
       JOIN FOODM f
            ON d.foodMaterial_Id = f.foodMaterial_Id
WHERE f.bId = #{bId}
  AND d.disposalDate >= #{startDate}
  AND d.disposalDate < #{endDate}

SELECT
COALESCE(SUM(d.disposalPrice), 0)
FROM DISPOSALS d
JOIN FOODM f
ON d.foodMaterial_Id = f.foodMaterial_Id
WHERE f.bId = #{bId}
AND d.disposalDate >= #{startDate}
AND d.disposalDate < #{endDate}
